namespace SirketMotoru.CanliPano;

internal static class YazilimBorsasiHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yazılım Borsası V9</title><style>
:root{color-scheme:dark;--bg:#040812;--p:#0b1525;--p2:#111f34;--l:#29415f;--t:#eef7ff;--m:#91a8c5;--g:#43e1a0;--b:#61a8ff;--r:#ff6b7d;--y:#ffd166}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 7% 0,#14365f 0,transparent 34%),radial-gradient(circle at 93% 0,#321c59 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:9px}.shell{max-width:2400px;margin:auto}.top{position:sticky;top:4px;z-index:20;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#071220f2}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px}.status,.tabs{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.tabs{margin:10px 0}.tab{cursor:pointer;border:1px solid var(--l);border-radius:999px;padding:8px 11px;background:#0a1628;color:var(--m);font-weight:900}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.ticker{overflow:hidden;white-space:nowrap;border:1px solid #765d2a;background:#21180c;border-radius:10px;margin:9px 0}.ticker div{display:inline-block;padding:9px 0;color:var(--y);font-size:10px;font-weight:800;animation:ticker 260s linear infinite}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.metrics{display:grid;grid-template-columns:repeat(9,minmax(105px,1fr));gap:7px}.metric,.item,.card{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.metric{padding:9px}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:5px;font-size:15px}.card{padding:12px;margin-bottom:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.item{padding:10px}.item h3{margin:0 0 4px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.title h2{margin:0;font-size:15px}.tablewrap{overflow:auto;max-height:760px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.bar{height:8px;background:#14233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:10px}.big{font-size:31px;font-weight:1000}.news{padding:8px 0;border-bottom:1px solid var(--l);font-size:10px}@media(max-width:1600px){.metrics{grid-template-columns:repeat(5,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.top{position:static;flex-direction:column;align-items:flex-start}.metrics,.grid,.grid4,.hero{grid-template-columns:1fr}}</style></head><body><div class="shell"><header class="top"><div class="brand">YAZILIM BORSASI V9<small>20.000 gerçek müşteri · trendli arz-talep · tek ekonomi defteri</small></div><div class="status"><span class="pill">Motor <b id="conn">Bağlanıyor</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panel">Ana Sayfa</b></span><span class="pill">Son veri <b id="time">—</b></span></div></header><div class="ticker"><div id="ticker">Piyasa hazırlanıyor…</div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><main id="root"></main></div><script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));const T=[['home','Ana Sayfa'],['market','Arz & Talep'],['companies','Şirketler'],['apps','Uygulamalar'],['os','İşletim Sistemleri'],['services','Hizmetler'],['customers','Müşteri CV'],['finance','Finans'],['news','Haberler'],['flow','Canlı Akış']];const S={d:null,a:T.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home',load:false,scroll:false,timer:null,last:-1};
function tabs(){$('#tabs').innerHTML=T.map(x=>`<button class="tab ${S.a===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('');$('#panel').textContent=T.find(x=>x[0]===S.a)?.[1]||S.a}function tab(id){if(!T.some(x=>x[0]===id))id='home';S.a=id;history.replaceState(null,'',`#${id}`);tabs();render()}async function refresh(force=false){if(S.load||S.scroll)return;S.load=true;try{const r=await fetch('/api/durum',{cache:'no-store'});S.d=await r.json();const t=Number(S.d.motor?.tickNumarasi||0);$('#conn').textContent='Çalışıyor';$('#tick').textContent=t;$('#time').textContent=new Date().toLocaleTimeString('tr-TR');if(force||t!==S.last){S.last=t;render()}ticker()}catch{$('#conn').textContent='Bağlantı yok'}finally{S.load=false}}
function metrics(d){const g=d.genel||{};return [['Bağlı şirket',`${int(g.bagliSirket)}/${int(g.toplamSirket)}`],['Müşteri',int(g.aktifMusteri)],['Hizmet talebi',int(g.hizmetTalebi)],['Karşılanan',int(g.hizmetKarsilanan)],['OS',`${int(g.osKarsilanan)}/${int(g.osTalebi)}`],['Uygulama geliri',money(g.toplamUygulamaGeliri)],['Hizmet geliri',money(g.toplamHizmetGeliri)],['Toplam gider',money(g.toplamGider)],['Piyasa neti',money(g.toplamNet)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}function render(){if(!S.d)return;const y=window.scrollY;$('#metrics').innerHTML=metrics(S.d);$('#root').innerHTML=({home,market,companies,apps,os,services,customers,finance,news,flow}[S.a]||home)(S.d);requestAnimationFrame(()=>window.scrollTo(0,y))}function ticker(){const h=S.d?.haberler||[];$('#ticker').textContent=h.slice(0,30).map(x=>`✦ ${x.baslik||x.tur||'Haber'} — ${x.aciklama||x.mesaj||''}`).join('       ')||'Piyasa sakin.'}
function home(d){const g=d.genel||{},o=d.isletimSistemiPazari||{},hp=g.hizmetTalebi?g.hizmetKarsilanan*100/g.hizmetTalebi:0,op=o.buTickTalep?o.karsilananTalep*100/o.buTickTalep:0;return `<div class="notice"><b>V9 temiz sezon:</b> Eski borç, destek ve çifte ekonomi katmanları silindi. Boş şirket düşük taban giderle yaşar; otomatik kredi yoktur.</div><div class="hero"><div class="card"><span class="sub">PİYASA HİZMET TALEBİ</span><div class="big">${int(g.hizmetTalebi)}</div><p>Karşılanan ${int(g.hizmetKarsilanan)} · açık ${int(g.hizmetTalebi-g.hizmetKarsilanan)}</p><div class="bar"><i style="width:${Math.min(100,hp)}%"></i></div><p>%${num(hp)} karşılanma</p></div><div class="card"><span class="sub">İŞLETİM SİSTEMİ</span><div class="big">${int(o.karsilananTalep)} / ${int(o.buTickTalep)}</div><div class="bar"><i style="width:${Math.min(100,op)}%"></i></div><p>Tüm aktif müşteriler OS talep eder.</p></div></div>${market(d)}${companies(d)}`}
function trend(x){return `<span class="${Number(x.degisimYuzdesi)>=0?'good':'bad'}">${Number(x.degisimYuzdesi)>=0?'▲':'▼'} %${num(Math.abs(x.degisimYuzdesi))}</span> ${esc(x.aktifTrend||'normal')}`}function market(d){const o=d.isletimSistemiPazari||{},a=d.uygulamaPazari||[],h=d.hizmetPazari||[];return `<div class="grid"><div class="card"><div class="title"><h2>Uygulama kategorileri</h2><span class="tag">${int(a.length)} pazar</span></div><div class="tablewrap"><table><tr><th>Kategori</th><th>Talep</th><th>Karşılanan</th><th>Arz</th><th>Açık</th><th>Trend</th></tr>${a.map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.arzKapasitesi)}</td><td class="${x.karsilanamayanTalep?'warn':'good'}">${int(x.karsilanamayanTalep)}</td><td>${trend(x)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>En güçlü hizmet trendleri</h2><div class="tablewrap"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>Trend</th><th>Fiyat</th></tr>${h.slice(0,120).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${trend(x)}</td><td>${money(x.sabitFiyat)}</td></tr>`).join('')}</table></div></div></div><div class="card"><h2>OS sağlayıcı dağılımı</h2><div class="grid4">${(o.arzDagilimi||[]).map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.sirketAdi)}</p><p><b>${int(x.karsilanan)}</b> müşteri · %${num(x.pazarPayi)}</p><p>Kapasite ${int(x.kapasite)} · ${money(x.fiyat)}</p></div>`).join('')||'<p>Aktif OS arzı yok.</p>'}</div></div>`}
function companies(d){return `<div class="grid4">${(d.sirketler||[]).map(s=>{const p=s.toplamKapasite?Math.min(999,s.kullanilanKapasite*100/s.toplamKapasite):0;return `<div class="item"><div class="title"><h3>${esc(s.sirketAdi)}</h3><span class="tag ${s.bagli?'good':'bad'}">${s.bagli?'BAĞLI':'KAPALI'}</span></div><p>Kasa <b>${money(s.kasa)}</b> · borç ${money(s.borc)}</p><p>Net <b class="${Number(s.netKazanc)>=0?'good':'bad'}">${money(s.netKazanc)}</b></p><p>Hizmet ${money(s.hizmetGeliri)} · uygulama ${money(s.uygulamaGeliri)}</p><p>Gider ${money(Number(s.isletmeGideri||0)+Number(s.finansmanGideri||0))}</p><p>Kapasite ${int(s.kullanilanKapasite)}/${int(s.toplamKapasite)} · %${num(p)}</p><div class="bar"><i style="width:${Math.min(100,p)}%"></i></div><p>Kalite ${num(s.kodKalitesiPuani)} · Perf ${num(s.performansPuani)} · Güv ${num(s.guvenlikPuani)}</p></div>`}).join('')}</div>`}
function apps(d){return `<div class="tablewrap card"><table><tr><th>Uygulama</th><th>Şirket</th><th>Tür / kategori</th><th>Durum</th><th>Kullanıcı</th><th>Kapasite</th><th>Kullanım</th><th>Fiyat</th><th>Gelir</th></tr>${(d.uygulamalar||[]).map(x=>{const m=x.manifest||{},u=x.urun||{},p=u.kullaniciKapasitesi?u.aktifKullaniciSayisi*100/u.kullaniciKapasitesi:0,f=u.fiyatlandirmaModeli==='kullanim'?u.kullanimBasinaUcret:u.abonelikUcreti;return `<tr><td><b>${esc(m.uygulamaAdi)}</b><br>${esc(m.uygulamaKimligi)}</td><td>${esc(x.sirketAdi)}</td><td>${esc(m.urunTuru)} / ${esc(m.kategori)}</td><td class="${u.aktif?'good':'warn'}">${u.aktif?'Aktif':x.piyasada?'Pasif':'Yayınlanmadı'}</td><td>${int(u.aktifKullaniciSayisi)}</td><td>${int(u.kullaniciKapasitesi)}</td><td>%${num(p)}</td><td>${money(f)}</td><td>${money(x.gelir)}</td></tr>`}).join('')}</table></div>`}
function os(d){const x=d.isletimSistemiPazari||{};return `<div class="notice">20.000 müşterinin tamamı aktif işletim sistemi talep eder. Kapasite yoksa bekleyen olur.</div><div class="grid4">${(x.arzDagilimi||[]).map(a=>`<div class="item"><h3>${esc(a.ad)}</h3><p>${esc(a.sirketAdi)}</p><div class="big">${int(a.karsilanan)}</div><p>%${num(a.pazarPayi)} pay · ${int(a.kapasite)} kapasite · ${money(a.fiyat)}</p></div>`).join('')}</div>`}
function services(d){return `<div class="notice">Hizmet fiyatı sabittir; rekabet kalite, hız, güvenlik ve kapasitededir.</div><div class="tablewrap card"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Arz</th><th>Açık</th><th>Fiyat</th><th>Sağlayıcılar</th></tr>${(d.hizmetPazari||[]).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.arzKapasitesi)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${money(x.sabitFiyat)}</td><td>${(x.arzDagilimi||[]).map(a=>`${esc(a.sirketAdi)}: ${int(a.karsilanan)} (%${num(a.pazarPayi)})`).join('<br>')||'—'}</td></tr>`).join('')}</table></div>`}
function customers(d){return `<div class="card"><div class="title"><h2>Müşteri CV</h2><span class="tag">Gerçek kalıcı tercihler</span></div><div class="tablewrap"><table><tr><th>Müşteri</th><th>Profil</th><th>Bakiye</th><th>OS</th><th>Uygulamalar</th><th>Harcama</th><th>İş başarısı</th><th>Sadakat</th></tr>${(d.musteriCvleri||[]).map(x=>`<tr><td><b>${esc(x.musteriAdi)}</b><br>${esc(x.musteriKimligi)}</td><td>${esc(x.meslekProfili)}<br>${esc(x.gelirSegmenti)}</td><td>${money(x.bakiye)}</td><td>${esc(x.isletimSistemiKimligi||'Bekliyor')}<br>${esc(x.isletimSistemiSirketKimligi||'')}</td><td>${(x.uygulamalar||[]).map(esc).join(', ')||'—'}</td><td>${money(x.toplamHarcama)}</td><td>${int(x.basariliIsSayisi)} / ${int(x.basarisizIsSayisi)}</td><td>${esc(x.tercihEdilenSirketKimligi||'—')}</td></tr>`).join('')}</table></div></div>`}
function finance(d){return `<div class="grid4">${(d.sirketler||[]).map(s=>`<div class="item"><h3>${esc(s.sirketAdi)}</h3><p>Hizmet <b class="good">${money(s.hizmetGeliri)}</b></p><p>Uygulama <b class="good">${money(s.uygulamaGeliri)}</b></p><p>Abonelik ${money(s.abonelikGeliri)} · protokol ${money(s.protokolGeliri)}</p><p>Gider <b class="bad">${money(Number(s.isletmeGideri||0)+Number(s.finansmanGideri||0))}</b></p><p>Net <b class="${Number(s.netKazanc)>=0?'good':'bad'}">${money(s.netKazanc)}</b> · borç ${money(s.borc)}</p></div>`).join('')}</div>`}function news(d){return `<div class="card"><h2>Haberler</h2>${(d.haberler||[]).slice(0,150).map(x=>`<div class="news"><b>${esc(x.baslik||x.tur||'Haber')}</b><br>${esc(x.aciklama||x.mesaj||'')}</div>`).join('')||'<p>Haber yok.</p>'}</div>`}function flow(d){return `<div class="tablewrap card"><table><tr><th>Zaman</th><th>Seviye</th><th>Mesaj</th></tr>${(d.olaylar||[]).slice().reverse().map(x=>`<tr><td>${esc(x.zaman||'')}</td><td>${esc(x.seviye||'')}</td><td>${esc(x.mesaj||'')}</td></tr>`).join('')}</table></div>`}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)tab(b.dataset.tab)});window.addEventListener('hashchange',()=>tab(location.hash.slice(1)));window.addEventListener('scroll',()=>{S.scroll=true;clearTimeout(S.timer);S.timer=setTimeout(()=>{S.scroll=false;refresh(false)},300)},{passive:true});tabs();refresh(true);setInterval(()=>refresh(false),1000);
</script></body></html>
""";
}
